// In C++11 and later, cbegin/cend simplify const-correct iteration.
std::vector<int> values = {10, 20, 30};

// Get a const_iterator from a non-const container.
auto it = values.cbegin();
// *it = 5; // Compile-time error: expression must be a modifiable lvalue

// Use in a find algorithm
auto pos = std::find(values.cbegin(), values.cend(), 20);

// For const containers, begin() and cbegin() are equivalent.
const std::vector<int> const_values = {40, 50, 60};
auto cit1 = const_values.begin();  // Type is const_iterator
auto cit2 = const_values.cbegin(); // Type is also const_iterator
